INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('WSDURC','Modulo per attivare le funzionalità di verifica dei documenti DURC esistenti e la richiesta di nuovi.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('WSDURC','SERVIZIO_ATTIVO','E'' il nome del servizio che fornisce le informazioni del DURC (WSDURC_INFODURC, ...)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('WSDURC','TIPODOC_ANAGRAFE','E'' la tipologia di documento che al quale associare il DURC o le richieste di verifica; viene anche utilizzata per determinare la data di scadenza qualora non presente nelle informazioni restituite.');
INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('WSDURC_INFODURC','Servizio di cooperazione applicativa per gestire le funzionalità di verifica e la richiesta dei documenti DURC implementato da NUOVAINFORMATICA per l''Osservatorio Cantieri Cassa Edile');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('WSDURC_INFODURC','INSTITUTECODE','Codice della Cassa Edile che fornisce il servizio (Es PR00); è comunicato dalla Cassa Edile.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('WSDURC_INFODURC','SOFTWARECODEID','Identificativo del software richiedente; il codice è rilasciato dal gestore tecnico del servizio Osservatorio (Nuova Informatica)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('WSDURC_INFODURC','USERID','Codice Utente autorizzato ad utilizzare i servizi ISG dell''Osservatorio Cantieri');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('WSDURC_INFODURC','USERPASSWORD','Password dell'' utente autorizzato ad utilizzare i servizi ISG dell''Osservatorio Cantieri');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO, DESCRIZIONE) VALUES ('WSDURC_INFODURC','URLWS_SERVIZIODURC','Indirizzo del wsdl dei servizi INFODURC ES:(STAGE: http://osservatorio.cassaedileweb.it/ServizioDURCTest/WSDurcServiceCE.asmx?WSDL, PRODUZIONE: https://osservatorio.cassaedileweb.it/ServizioDURC/WSDurcServiceCE.asmx?WSDL). Per la produzione è necessario installare nella jvm i certificati rilasciati da NUOVAINFORMATICA');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCER', 'URL_REG_PARTICOLARE', 'Il sistema standard docer ha un web service apposito creato per gestire solo il sistema di registrazione particolare, dentro questo parametro va indicato, appunto, l''end point del servizio che gestisce la registrazione particolare');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_HALLEY', 'RADICE_ALBERO_EDILIZIA', 'Questa funzionalità si attiva solamente se il parametro GENERA_SUAP_XML è valorizzato a 1, va indicata la radice dell''albero dell''edilizia (ad esempio 04, 07 o 0401....) serve per specificare se la pratica è relativa all''edilizia in fase di creazione SUAP o SUEXML. Il sistema infatti, in fase di protocollazione istanza, andrà a verificare se l''intervento specificato ha la stessa radice indicata in questo parametro, in caso positivo si andrà a creare il file SUEXML, altrimenti SUAPXML, in sostanza è la discriminante tra la creazione per il SUAP e il SUE');
