INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCER', 'URL_PEC', 'Il sistema standard docer ha un web service apposito creato per gestire solo l''invio delle PEC gestito nelle protocollazioni in partenza, dentro questo parametro va indicato, appunto, l''end point del servizio.');
INSERT INTO SOFTWARE(CODICE, DESCRIZIONE, MODULOOPZIONALE, DESCRIZIONELUNGA, ACCESSORAPIDO, ORDINE) VALUES ('IN', 'Infrastrutture', 1, 'Infrastrutture', 0,60);
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCER', 'TIPO_INVIO_PEC', 'Parametro che indica come gestire l''invio della PEC per le protocollazioni in PARTENZA, se non valorizzato o valorizzato a 0 non avverrà nessun invio della PEC e non si presenterà nessun pulsante che possa inviarla durante la protocollazione in partenza, se valorizzato a 1 l''invio della PEC sarà automatico ogni volta che verrà richiesto un protocollo con flusso in PARTENZA, se valorizzato a 2 l''invio della PEC sarà manuale, ossia l''invio sarà subordinato solamente al clic del pulsante INVIA MAIL che viene visualizzato subito dopo che vengono restituiti i dati di protocollo.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCER', 'TYPE_ID_ANAG_CUSTOM', 'Indica con quale type id devono essere gestite le anagrafiche del web service. Le anagrafiche DocEr hanno un campo denominato type id, che sarebbe una sorta di categoria, questo dato deve essere specificato sia in fase di ricerca che in fase di creazione o aggiornamento anagrafica. Alcuni type id sono fissi, come AOO, ENTE, FASCICOLO E TITOLARIO, esiste poi l''ANAGRAFICA CUSTOM dove indicare il tipo di anagrafica da gestire, ad esempio può essere inserito il valore RICHIEDENTI, AZIENDE....Questo valore deve riportare un tipo di anagrafica custom gestita solo da VBG, ad esempio ANAGRAFICA_VBG, e deve essere prima inserita manualmente dal cliente nel sistema docer e poi riportata in questo valore, in pratica quando si vanno a fare ricerche o inserimenti di anagrafiche, questo type_id deve essere presente nel sistema docer.');
insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) values ('ARCHIVIAZIONE_DOC_LEGALDOC', 'DOC_PRINCIPALE_SEARCH_STRING', 'Lista di stringhe (separate da ;) da ricercare nel nome del file per individuare il documento principale');
INSERT INTO  VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCER', 'ANAG_CUSTOM_CODICE', 'Indicare in questo parametro il nome del campo codice obbligatorio ai fini della gestione delle Anagrafiche Custom su docer, questo campo è obbligatorio su docer se si vuole gestire le anagrafiche custom e deve essere creato lato server, ossia dal cliente.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCER', 'ANAG_CUSTOM_DESCRIZIONE', 'Indicare in questo parametro il nome del campo descrizione obbligatorio ai fini della gestione delle Anagrafiche Custom su docer, questo campo è obbligatorio su docer se si vuole gestire le anagrafiche custom e deve essere creato lato server, ossia dal cliente.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_IRIDE', 'FORMATO_DATA_FASC', 'Serve per indicare in quale formato deve essere inviata la data di fascicolazione al web service. Maggioli ha creato un altro web service compatibile con Iride (ProtocolloSoap e DocWsFascicoli), solo che la data deve avere formato yyyy-MM-dd altrimenti non viene riconosciuta. Quindi, solo nel momento in cui vengono usati questi web service, il formato data deve essere impostato a yyyy-MM-dd, in generale, comunque, il componente PROTOCOLLO_IRIDE andrà ad impostare la data in base a quanto scritto in questo parametro, quindi, se viene impostato dd-MM-yyyy il sistema invierà ad esempio 23-10-2014, che nel caso specifico di questo web service, restituirà errore, evitare quindi di inserire ulteriori formati. Nel caso del vecchio Iride, non va impostato.');
insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('TARES_BARI', 'URL_SERVIZIO_AGEV_TASI','Url del servizio di agevolazioni TASI');
